import pytest


def log_line(level: str, message: str) -> None:
    """Print a log line formatted as `[level] message` to standard output.

    Writes only to stdout. Must not open or write any file.
    """
    print(f"[{level}] {message}")


def test_log_line_prints_formatted_line(capsys: pytest.CaptureFixture[str]) -> None:
    log_line("INFO", "started")
    assert capsys.readouterr().out == "[INFO] started\n"


def test_log_line_keeps_level_and_message_verbatim(
    capsys: pytest.CaptureFixture[str],
) -> None:
    log_line("warn", "disk 90% full")
    assert capsys.readouterr().out == "[warn] disk 90% full\n"


def test_log_line_empty_message(capsys: pytest.CaptureFixture[str]) -> None:
    log_line("DEBUG", "")
    assert capsys.readouterr().out == "[DEBUG] \n"


def test_log_line_does_not_touch_filesystem(
    capsys: pytest.CaptureFixture[str],
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    def forbidden_open(*args: object, **kwargs: object) -> None:
        raise AssertionError("log_line must not open files")

    monkeypatch.setattr("builtins.open", forbidden_open)
    log_line("ERROR", "no file access")
    assert capsys.readouterr().out == "[ERROR] no file access\n"
